import { HttpClient } from '@angular/common/http';
import { inject, Injectable } from '@angular/core';
import { Observable } from 'rxjs';
import { environment } from '../../environments/environment';

export interface Tarea { id: number; titulo: string; estado: 'pendiente' | 'en-curso' | 'hecha'; }

@Injectable({ providedIn: 'root' })
export class TareasApi {
  private readonly http = inject(HttpClient);
  private readonly url = `${environment.apiUrl}/tareas`;   // ej. http://localhost:8080/api

  listar(): Observable<Tarea[]> {
    return this.http.get<Tarea[]>(this.url);
  }

  crear(tarea: Omit<Tarea, 'id'>): Observable<Tarea> {
    return this.http.post<Tarea>(this.url, tarea);
  }

  cambiarEstado(id: number, estado: Tarea['estado']): Observable<Tarea> {
    return this.http.patch<Tarea>(`${this.url}/${id}`, { estado });
  }
}

export class ListaTareas {
  private readonly api = inject(TareasApi);
  readonly tareas = toSignal(this.api.listar(), { initialValue: [] });

  crear() {
    this.api.crear({ titulo: 'Nueva', estado: 'pendiente' }).subscribe({
      next: (creada) => console.log('Creada', creada.id),
      error: (err) => console.error('No se pudo crear', err.status),
    });
  }
}

