import { Component, inject } from '@angular/core';
import { toSignal } from '@angular/core/rxjs-interop';
import { TareasApi } from './tareas-api';

@Component({
  selector: 'app-root',
  template: `
    <h1>Tareas desde la API</h1>
    <ul>
      @for (t of tareas(); track t.id) {
        <li>{{ t.titulo }} ({{ t.estado }})</li>
      }
    </ul>
  `,
})
export class App {
  private readonly api = inject(TareasApi);
  protected readonly tareas = toSignal(this.api.listar(), { initialValue: [] });
}
